  ('Are You a Morning Person?', '{"prompt":"What is a chronotype?","options":["The natural timing of a person''s body clock","A way of measuring intelligence","A type of alarm clock","A sleep disorder"],"correctIndex":0}', 1),
  ('Are You a Morning Person?', '{"prompt":"According to the text, why do night owls often have night-owl parents?","options":["They copy their parents'' habits","The tendency is partly inherited","They live in the same time zone","Their parents keep them awake"],"correctIndex":1}', 2),
  ('Are You a Morning Person?', '{"prompt":"What usually happens to the body clock during the teenage years?","options":["It becomes exactly twenty-four hours","It shifts earlier","It shifts later","It stops changing"],"correctIndex":2}', 3),
  ('Are You a Morning Person?', '{"prompt":"Why are evening types at a disadvantage?","options":["They are less intelligent","They eat at the wrong times","They sleep less in total","Schools and workplaces mostly start early"],"correctIndex":3}', 4),
  ('Are You a Morning Person?', '{"prompt":"What does the writer suggest at the end?","options":["Know your rhythm and do hard tasks at your best hours","Schools should start at noon","Night owls should force themselves to wake at six","Changing your body clock is impossible"],"correctIndex":0}', 5),
  ('The Trouble with Five Stars', '{"prompt":"What does the writer mean by \"inflation\" in ratings?","options":["Most ratings bunching at four or five stars","Too many people writing reviews","Ratings falling over time","Prices rising because of reviews"],"correctIndex":0}', 1),
  ('The Trouble with Five Stars', '{"prompt":"Why do many people round their rating up, according to the text?","options":["Platforms force them to","Giving less than five stars feels like punishing someone","They are paid to do so","They don''t read the scale"],"correctIndex":1}', 2),
  ('The Trouble with Five Stars', '{"prompt":"What has five stars come to mean?","options":["The product is new","The service was outstanding","Nothing went wrong","The customer was paid"],"correctIndex":2}', 3),
  ('The Trouble with Five Stars', '{"prompt":"Which customers are most likely to write reviews?","options":["Those who bought nothing","Only professional reviewers","Those who were merely satisfied","Those who were delighted or furious"],"correctIndex":3}', 4),
  ('The Trouble with Five Stars', '{"prompt":"What does the writer recommend?","options":["Reading moderate, three-star reviews","Writing only five-star reviews","Ignoring reviews completely","Trusting only the average score"],"correctIndex":0}', 5),
  ('When a Measure Becomes a Target', '{"prompt":"What does Goodhart''s law state, as described in the text?","options":["When a measure becomes a target, it stops being a good measure","Economists should not set targets","Every organisation needs more measures","Statistics are always unreliable"],"correctIndex":0}', 1),
  ('When a Measure Becomes a Target', '{"prompt":"In the hospital example, what may happen once waiting time becomes a target?","options":["Hospitals hire more doctors","Patients are seen briefly to stop the clock and then wait elsewhere","Waiting times are no longer recorded","Patients choose other hospitals"],"correctIndex":1}', 2),
  ('When a Measure Becomes a Target', '{"prompt":"According to the writer, why does the problem persist even without dishonesty?","options":["The measures are calculated incorrectly","People ignore the rules","Individuals respond sensibly to incentives and the distortion comes from the system","Managers deliberately hide the truth"],"correctIndex":2}', 3),
  ('When a Measure Becomes a Target', '{"prompt":"Why does adding more measures rarely help?","options":["Nobody reads them","They contradict each other","They are too expensive","Each new measure becomes another target that can be gamed"],"correctIndex":3}', 4),
  ('When a Measure Becomes a Target', '{"prompt":"What is the writer''s attitude to a single, objective score?","options":["It should be viewed with suspicion","It is only useful in hospitals","It is impossible to calculate","It is the best solution available"],"correctIndex":0}', 5)
