insert into public.reading_open_questions (reading_text_id, question_en, sort_order)
select rt.id, gen.question_en, gen.sort_order
from public.reading_texts rt
join (values
  ('The Book Swap on Our Street', 'Would a book swap work on your street? Why or why not?', 1),
  ('The Book Swap on Our Street', 'What is something you own that you would like other people to use? Explain.', 2),
  ('Are You a Morning Person?', 'Are you a morning person or a night owl? How does it affect your day?', 1),
  ('Are You a Morning Person?', 'Should schools start later for teenagers? Give reasons for your opinion.', 2),
  ('The Trouble with Five Stars', 'How do you use online reviews when you buy something? Has a review ever misled you?', 1),
  ('The Trouble with Five Stars', 'Should rating systems be designed differently? Suggest one change and explain why it would help.', 2),
  ('When a Measure Becomes a Target', 'Think of a target in your school, workplace or daily life. Has it ever been reached in a way that missed its real purpose?', 1),
  ('When a Measure Becomes a Target', 'Is it possible to measure success without creating the problem the text describes? Discuss.', 2)
) as gen(title_en, question_en, sort_order)
